WHERE SC.NAME = 'ARTÍFICE'
  AND ST.NAME = 'Outros'
  AND NOT EXISTS (
      SELECT 1 FROM SERVICE_FIELD_TYPE SFT
      WHERE SFT.ID_SERVICE_TYPE = ST.ID
        AND SFT.NAME = 'Foto da necessidade'
  );

