-- 14. REQUEST
-- ============================================================

-- Os IDs históricos acima são explícitos e, por isso, não avançam a sequence da
-- coluna identity. Sincronize-a para que a próxima REQUEST use MAX(ID) + 1.
SELECT setval(
    pg_get_serial_sequence('request', 'id'),
    COALESCE(MAX(ID), 1),
    MAX(ID) IS NOT NULL
)
FROM REQUEST;

-- ============================================================
-- 15. SERVICE_FIELD_VALUE
-- ============================================================
-- Parte 3/3. Execute após INSERT_REQUEST.sql na mesma sessão/transação; este arquivo finaliza com COMMIT.
-- ================================================================
-- SERVICE_FIELD_VALUE
-- Fonte: somente colunas preenchidas do Excel que possuem uma definição
-- correspondente em SERVICE_FIELD_TYPE para Categoria + Chamado.
--
-- Regras de conversão para VALUE JSONB:
--   TEXT/SINGLE_SELECT/DATE -> string JSON
--   NUMBER                  -> número JSON
--   BOOL                    -> true/false JSON
--   MULTI_SELECT            -> array JSON
--
-- Valores vazios, somente '-' e a imagem padrão not-found-deskbee.jpg
-- não geram registros.
-- Registros preparados: 4166
-- Solicitações com pelo menos um campo preenchido: 797
-- ================================================================
CREATE TEMP TABLE TMP_SERVICE_FIELD_VALUE_IMPORT (
    IMPORT_ROW_ID BIGINT NOT NULL,
    FIELD_NAME TEXT NOT NULL,
    FIELD_TYPE TEXT NOT NULL,
    VALUE JSONB NOT NULL
) ON COMMIT DROP;










-- Validações das referências antes do INSERT.
DO $$
DECLARE
    V_ERROR_COUNT INTEGER;
BEGIN
    SELECT COUNT(*)
      INTO V_ERROR_COUNT
      FROM TMP_SERVICE_FIELD_VALUE_IMPORT V
     WHERE NOT EXISTS (
         SELECT 1
         FROM TMP_REQUEST_IMPORT T
         WHERE T.IMPORT_ROW_ID = V.IMPORT_ROW_ID
     );
    IF V_ERROR_COUNT > 0 THEN
        RAISE EXCEPTION '% valores não possuem linha correspondente em TMP_REQUEST_IMPORT.', V_ERROR_COUNT;
    END IF;

    SELECT COUNT(*)
      INTO V_ERROR_COUNT
      FROM TMP_SERVICE_FIELD_VALUE_IMPORT V
      JOIN TMP_REQUEST_IMPORT T
        ON T.IMPORT_ROW_ID = V.IMPORT_ROW_ID
     WHERE (
         SELECT COUNT(*)
         FROM SERVICE_CATEGORY SC
         JOIN SERVICE_TYPE ST
           ON ST.ID_SERVICE_CATEGORY = SC.ID
         JOIN SERVICE_FIELD_TYPE SFT
           ON SFT.ID_SERVICE_TYPE = ST.ID
         WHERE UPPER(BTRIM(SC.NAME)) = UPPER(BTRIM(T.CATEGORY_NAME))
           AND UPPER(BTRIM(ST.NAME)) = UPPER(BTRIM(T.SERVICE_TYPE_NAME))
           AND UPPER(BTRIM(SFT.NAME)) = UPPER(BTRIM(V.FIELD_NAME))
           AND UPPER(BTRIM(SFT.TYPE::TEXT)) = UPPER(BTRIM(V.FIELD_TYPE))
     ) <> 1;
    IF V_ERROR_COUNT > 0 THEN
        RAISE EXCEPTION '% valores possuem SERVICE_FIELD_TYPE ausente ou duplicado.', V_ERROR_COUNT;
    END IF;

    SELECT COUNT(*)
      INTO V_ERROR_COUNT
      FROM TMP_SERVICE_FIELD_VALUE_IMPORT V
      JOIN TMP_REQUEST_IMPORT T
        ON T.IMPORT_ROW_ID = V.IMPORT_ROW_ID
     WHERE NOT EXISTS (
         SELECT 1
         FROM REQUEST R
         WHERE R.ID = T.ID_REQUEST
     );
    IF V_ERROR_COUNT > 0 THEN
        RAISE EXCEPTION '% valores não possuem REQUEST inserida.', V_ERROR_COUNT;
    END IF;
END;
$$;

WITH INSERTED_SERVICE_FIELD_VALUES AS (
        ID_SERVICE_FIELD_TYPE,
        ID_REQUEST,
        VALUE
    )
    SELECT
        SFT.ID AS ID_SERVICE_FIELD_TYPE,
        T.ID_REQUEST AS ID_REQUEST,
        V.VALUE
    FROM TMP_SERVICE_FIELD_VALUE_IMPORT V
    JOIN TMP_REQUEST_IMPORT T
      ON T.IMPORT_ROW_ID = V.IMPORT_ROW_ID
    JOIN SERVICE_CATEGORY SC
      ON UPPER(BTRIM(SC.NAME)) = UPPER(BTRIM(T.CATEGORY_NAME))
    JOIN SERVICE_TYPE ST
      ON ST.ID_SERVICE_CATEGORY = SC.ID
     AND UPPER(BTRIM(ST.NAME)) = UPPER(BTRIM(T.SERVICE_TYPE_NAME))
    JOIN SERVICE_FIELD_TYPE SFT
      ON SFT.ID_SERVICE_TYPE = ST.ID
     AND UPPER(BTRIM(SFT.NAME)) = UPPER(BTRIM(V.FIELD_NAME))
     AND UPPER(BTRIM(SFT.TYPE::TEXT)) = UPPER(BTRIM(V.FIELD_TYPE))
    RETURNING ID
)
SELECT COUNT(*) AS SERVICE_FIELD_VALUES_INSERTED
FROM INSERTED_SERVICE_FIELD_VALUES;


